59	function rateLimit(tier) {
60	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
61	  return (req, res, next) => {
62	    const key = `${tier}:${req.ip}`;
63	    const now = Date.now();
64	    let entry = rateLimitMap.get(key);
65	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
66	      entry = { start: now, count: 0 };
67	      rateLimitMap.set(key, entry);
68	    }
69	    entry.count++;
70	    if (entry.count > max) {
71	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
72	    }
73	    next();
74	  };
75	}
