77	// Cleanup stale entries every 5 minutes
78	setInterval(() => {
79	  const now = Date.now();
80	  for (const [key, entry] of rateLimitMap) {
81	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
82	  }
83	}, 300_000);
